{# ═══════════════════════════════════════════════════════════════════════
   NLSAT Offer Letter — Unified Print Format (FIXED)
   Covers: LLB (Hons.), BA (Hons.), 5-Year Integrated B.A. LL.B. (Hons.), MPP
   DocType: Offer Letter   |   Engine: Jinja

   FIXES APPLIED vs previous version:
     1. Removed 5 phantom blank pages (page-break restructured to sibling
        marker divs instead of wrapping content in the break div)
     2. Fixed numbered-list marker clipping ("10." -> "0.") via CSS counters
     3. Removed stray empty 4th column in Appendix II Deposits table
     4. Linux-safe serif font stack (+ optional @font-face slot)
     5. Programme classification now reads explicit DocType fields first,
        with name-substring matching only as a last-resort fallback
     6. Fixed candidate_name / campus display-field dereferencing
     7. Added page-break-inside:avoid on tables, list items, FAQ blocks
     8. Logo given fixed box + block centering so it can't drift
   ═══════════════════════════════════════════════════════════════════════ #}



{# ── 0. GLOBAL CONFIGURABLE VARIABLES (UPDATE YEARLY) ── #}
{% set static_base_url = frappe.utils.get_url() %}

{% set var_registration_date = "29 June 2026" %}
{% set var_orientation_date = "30 June 2026" %}
{% set var_classes_begin_date = "1 July 2026" %}
{% set var_bachelors_deadline = "31 December 2026" %}

{% set var_ba_fin_aid_deadline = "07 July 2026" %}
{% set var_llb_fin_aid_deadline = "19 June 2026" %}
{% set var_mpp_fin_aid_deadline = "07 July 2026" %}

{% set var_fin_aid_decision_date = "31 July 2026" %}

{% set var_ba_housing_fee = "1,32,800" %}
{% set var_llb_housing_fee = "1,88,200" %}
{% set var_mpp_housing_fee = "1,88,200" %}

{% set var_ba_tuition_fee = "3,18,200" %}
{% set var_llb_tuition_fee = "3,18,200" %}
{% set var_mpp_tuition_fee = "3,18,200" %}

{% set var_ba_scst_total = "4,83,700" %}
{% set var_ba_gen_total = "4,88,600" %}

{% set var_llb_scst_total = "5,39,100" %}
{% set var_llb_gen_total = "5,44,000" %}

{% set var_mpp_scst_total = "5,39,100" %}
{% set var_mpp_gen_total = "5,44,000" %}

{% set var_admission_fee = "13,900" %}
{% set var_scst_deposit = "18,800" %}
{% set var_gen_deposit = "23,700" %}

{# ── 1. FETCH LINKED DOCUMENTS ── #}
{% set campus = frappe.get_doc("Campus", doc.campus) if doc.campus else None %}
{% set applicant = frappe.get_doc("Applicant", doc.applicant) if doc.applicant else None %}
{% set programme = frappe.get_doc("Programme", doc.program) if doc.program else None %}
{% set issued_date = doc.issued_on or frappe.utils.today() %}

{# ── FIX #6: correct display-name dereferencing, with safe fallbacks ── #}
{% set candidate_display_name =
      (applicant.candidate_name if applicant and applicant.candidate_name else None)
      or (applicant.applicant_name if applicant and applicant.get("applicant_name") else None)
      or (doc.candidate_name if doc.get("candidate_name") else None)
      or "Candidate" %}

{% set campus_city_display =
      (campus.city if campus and campus.get("city") else None)
      or (campus.campus_name if campus and campus.campus_name else None)
      or "Bengaluru" %}

{# ── 2. PROGRAMME IDENTIFICATION ──
   FIX #5: Prefer explicit fields on the Programme master. Only fall back
   to guessing from the programme name if those fields are genuinely blank.
   ACTION REQUIRED (see checklist below the code): populate on every
   Programme record:
     - programme_type   (Select: "UG" / "PG")
     - program_duration  (Int: total years, e.g. 3, 2, or 5 for integrated)
     - housing_model     (Select: "On-Campus" / "Off-Campus") -- optional,
       else derived from programme_type
#}
{% set pn = (doc.program or "").upper() %}
{% set explicit_type = (programme.programme_type if programme and programme.get("programme_type") else "") | upper %}
{% set prog_duration = (programme.program_duration if programme and programme.program_duration else None) %}

{% if explicit_type == "UG" %}
  {% set is_ug = true %}
{% elif explicit_type == "PG" %}
  {% set is_ug = false %}
{% else %}
  {# Fallback only if programme_type was left blank on the master.
     Strips punctuation before substring matching so "B.A., LL.B." style
     names classify correctly. #}
  {% set pn_clean = pn.replace(".", "").replace(",", "").replace(" ", "") %}
  {% set is_ug = ("BA" in pn_clean and "LLB" not in pn_clean) or (programme and programme.level_of_study == "Undergraduate") %}
{% endif %}
{% set is_pg = not is_ug %}

{% if not prog_duration %}
  {% set pn_clean = pn.replace(".", "").replace(",", "").replace(" ", "") %}
  {% if "5YEAR" in pn_clean or ("BA" in pn_clean and "LLB" in pn_clean) %}
    {% set prog_duration = 5 %}
  {% elif is_pg and ("MPP" in pn_clean or "PUBLICPOLICY" in pn_clean) %}
    {% set prog_duration = 2 %}
  {% elif is_pg %}
    {% set prog_duration = 3 %}
  {% else %}
    {% set prog_duration = 3 %}
  {% endif %}
{% endif %}

{% set pn_clean = pn.replace(".", "").replace(",", "").replace(" ", "") %}
{% set is_integrated_ba_llb = is_ug and "LLB" in pn_clean %}
{% set is_mpp = is_pg and (prog_duration == 2 or "MPP" in pn_clean or "PUBLICPOLICY" in pn_clean) %}
{% set is_llb = is_pg and not is_mpp %}
{% set is_ba = is_ug %}

{# ── 3. PROGRAMME DISPLAY NAMES ── #}
{% if is_integrated_ba_llb %}
  {% set prog_display = doc.program or "5-Year B.A., LL.B. (Hons.)" %}
  {% set fee_table_title = "Programme Fees for " ~ prog_display ~ " Programme" %}
{% elif is_llb %}
  {% set prog_display = "LL.B. (Hons.)" %}
  {% set fee_table_title = "Programme Fees for LLB. (Hons) Programme" %}
{% elif is_ba %}
  {% set prog_display = "BA (Hons.)" %}
  {% set fee_table_title = "Programme Fees for BA (Hons.) Programme" %}
{% elif is_mpp %}
  {% set prog_display = "Master's Programme in Public Policy" %}
  {% set fee_table_title = "Programme Fees for Master's Programme in Public Policy" %}
{% else %}
  {% set prog_display = doc.program or "Programme" %}
  {% set fee_table_title = "Programme Fees for " ~ prog_display %}
{% endif %}

{# ── 4. HOUSING TERMINOLOGY ── #}
{% set housing_option_label = "University housing" if is_ba else "Off-Campus Accommodation" %}
{% set housing_fee_label = "Housing Fee" if is_ba else "Off-Campus Housing Fee" %}
{% set housing_includes_label = housing_fee_label %}

{# ── 5. DATES ── #}
{% if doc.confirmation_fee_deadline %}
  {% set confirmation_deadline = frappe.utils.format_date(doc.confirmation_fee_deadline, "d MMMM yyyy") %}
{% else %}
  {% set confirmation_deadline = "19 June 2026" if is_llb else "25 June 2026" %}
{% endif %}

{% if doc.payment_deadline %}
  {% set full_fee_deadline = frappe.utils.format_date(doc.payment_deadline, "d MMMM yyyy") %}
{% else %}
  {% set full_fee_deadline = "24 June 2026" if is_llb else "27 June 2026" %}
{% endif %}

{% set financial_aid_deadline = doc.financial_aid_deadline_display or ("19 June 2026" if is_llb else "07 July 2026") %}
{% set registration_date = doc.registration_date_display or "29 June 2026" %}
{% set orientation_date = doc.orientation_date_display or "30 June 2026" %}
{% set classes_begin_date = doc.classes_begin_date_display or "1 July 2026" %}
{% set bachelors_deadline = "31 December 2026" %}
{% set academic_yr = doc.academic_year or "2026-2027" %}

{# ── 6. FEE DATA (per programme) ──
   NOTE: These remain hardcoded per your explicit instruction. If NLSIU
   revises fee slabs again, this is the single block to edit — search for
   "FEE DATA BLOCK" in this file. Long-term, move this into a Fee Schedule
   child table on the Programme/Offer Letter doctype instead of hardcoding.
#}
{% set admission_fee = "13,900" %}
{% set tuition_fee = "3,18,200" %}
{% set scst_deposit = "18,800" %}
{% set gen_deposit = "23,700" %}
{% set confirmation_fee_amt = "30,000" %}

{% if is_integrated_ba_llb %}
  {% set housing_fee = "1,32,800" %}
  {% set total_y1 = "4,64,900" %}
  {% set total_y2 = "4,51,000" %}
  {% set total_yN = "4,51,000" %}
  {% set total_programme = "22,69,700" %}
  {% set total_tuition_all = "15,91,000" %}
  {% set total_housing_all = "6,64,000" %}
  {% set total_scst_y1 = "4,83,700" %}
  {% set total_gen_y1 = "4,88,600" %}
{% elif is_ba %}
  {% set housing_fee = "1,32,800" %}
  {% set total_y1 = "4,64,900" %}
  {% set total_y2 = "4,51,000" %}
  {% set total_yN = "4,51,000" %}
  {% set total_programme = "13,66,900" %}
  {% set total_tuition_all = "9,54,600" %}
  {% set total_housing_all = "3,98,400" %}
  {% set total_scst_y1 = "4,83,700" %}
  {% set total_gen_y1 = "4,88,600" %}
{% elif is_mpp %}
  {% set housing_fee = "1,88,200" %}
  {% set total_y1 = "5,20,300" %}
  {% set total_y2 = "5,06,400" %}
  {% set total_yN = "5,06,400" %}
  {% set total_programme = "10,26,700" %}
  {% set total_tuition_all = "6,36,400" %}
  {% set total_housing_all = "3,76,400" %}
  {% set total_scst_y1 = "5,39,100" %}
  {% set total_gen_y1 = "5,44,000" %}
{% else %}
  {% set housing_fee = "1,88,200" %}
  {% set total_y1 = "5,20,300" %}
  {% set total_y2 = "5,06,400" %}
  {% set total_yN = "5,06,400" %}
  {% set total_programme = "15,51,900" %}
  {% set total_tuition_all = "9,54,600" %}
  {% set total_housing_all = "5,64,600" %}
  {% set total_scst_y1 = "5,39,100" %}
  {% set total_gen_y1 = "5,44,000" %}
{% endif %}

{% set no_housing_scst = "3,50,900" %}
{% set no_housing_gen = "3,55,800" %}

{# ── 7. UNIVERSITY INFO ── #}
{% set uni_name = campus.campus_name if campus and campus.campus_name else "National Law School of India University" %}
{% set uni_short = "NLSIU" %}
{% set uni_address = (campus.address if campus and campus.address else "Post Bag No. 7201, NAGARBHAVI, BENGALURU - 560 242. (Old Code No. 560 072), INDIA.") %}
{% set uni_phone = campus.phone_number if (campus and campus.phone_number) else "080- 23010000" %}
{% set uni_email = campus.email if (campus and campus.email) else "contactus@nls.ac.in/nlsat.query@nls.ac.in" %}

{# ══════════════════════════════════════════════════════════════════════ #}
{# CSS STYLES                                                              #}
{# ══════════════════════════════════════════════════════════════════════ #}
<style>

/* ---------- Optional: embed a real serif TTF for pixel-parity -----------
   Drop a licensed serif font (e.g. Noto Serif / your NLSIU brand serif)
   into this app's /public/fonts/ folder and uncomment. This guarantees
   identical rendering regardless of what's installed on the PDF server.

@font-face {
  font-family: 'NLSATSerif';
  src: url('/assets/slcm/fonts/NotoSerif-Regular.ttf') format('truetype');
  font-weight: 400;
}
@font-face {
  font-family: 'NLSATSerif';
  src: url('/assets/slcm/fonts/NotoSerif-Bold.ttf') format('truetype');
  font-weight: 700;
}
------------------------------------------------------------------------- */

@page { size: A4; margin: 15mm 18mm 20mm 18mm; }

/* ---------- Global ---------- */
.nlsat-offer {
  /* FIX #4: Linux-safe serif stack. 'Times New Roman' does not exist on
     the Linux server running wkhtmltopdf and was silently substituted,
     which is why the rendered font didn't match. If you embed the
     @font-face above, put 'NLSATSerif' first in this list. */
  font-family: 'Noto Serif', 'Liberation Serif', 'DejaVu Serif', Georgia, 'Times New Roman', serif;
  color: #1a1a1a;
  font-size: 11pt;
  line-height: 1.55;
}
.nlsat-offer * { box-sizing: border-box; }

/* ---------- FIX #1: page-break architecture -----------------------------
   Never wrap section content inside the page-break element itself.
   Use an EMPTY sibling marker div before each section instead. This is
   the pattern that avoids wkhtmltopdf's phantom blank page bug. #}
.section { }
.section-break { page-break-before: always !important; }
/* Defensive: never let the letterhead block itself be split across a
   page boundary, even if the underlying PDF engine mishandles a break. */
.lh { page-break-inside: avoid !important; page-break-after: avoid !important; }

/* ---------- Letterhead ---------- */
.lh { text-align: center; padding-bottom: 8px; margin-bottom: 16px; }
.lh img.logo { display: block; margin: 0 auto 6px; width: 70px; height: 65px; object-fit: contain; }
.lh-name { font-size: 14pt; font-weight: 700; text-transform: uppercase; letter-spacing: 0.03em; margin: 0 0 2px; }
.lh-addr { font-size: 9.5pt; color: #333; margin: 0; }
.lh-phone { font-size: 9.5pt; color: #333; margin: 0; }
.lh-email { font-size: 9.5pt; color: #333; margin: 0 0 4px; }

/* ---------- Body text ---------- */
.para { text-align: justify; margin-bottom: 10px; orphans: 2; widows: 2; }
.bold { font-weight: 700; }

/* ---------- Appendix titles ---------- */
.app-title { text-align: center; font-size: 12pt; font-weight: 700; margin: 12px 0 4px;color: #900; }
.app-subtitle { text-align: center; font-size: 11pt; font-weight: 700; margin: 0 0 16px;color: #900; }

/* ---------- FIX #2: CSS-counter based numbered lists -------------------
   Native <ol><li> markers get clipped by wkhtmltopdf once they reach two
   digits ("10." renders as "0."). Using an explicit counter with a fixed-
   width ::before marker box avoids this entirely, at any digit count. #}
.step-list { list-style: none; counter-reset: step; padding-left: 0; margin: 10px 0; }
.step-list > li {
  counter-increment: step;
  position: relative;
  padding-left: 30px;
  margin-bottom: 8px;
  text-align: justify;
  page-break-inside: avoid;
}
.step-list > li::before {
  content: counter(step) ".";
  position: absolute;
  left: 0;
  top: 0;
  width: 26px;
  font-weight: 400;
}

.sub-list { list-style: none; counter-reset: substep; margin: 6px 0 6px 4px; padding-left: 0; }
.sub-list > li {
  counter-increment: substep;
  position: relative;
  padding-left: 24px;
  margin-bottom: 4px;
  page-break-inside: avoid;
}
.sub-list > li::before {
  content: counter(substep, lower-alpha) ".";
  position: absolute;
  left: 0;
  top: 0;
  width: 20px;
}

.note-text { font-size: 10pt; margin-top: 6px; font-style: italic; color: #333; page-break-inside: avoid; }

/* ---------- Fee table ---------- */
.fee-table { width: 100%; border-collapse: collapse; font-size: 10pt; margin: 12px 0; page-break-inside: avoid; }
.fee-table th, .fee-table td { border: 1px solid #666; padding: 6px 8px; text-align: center; vertical-align: middle; }
.fee-table th { background: #f5f5f5; font-weight: 700; }
.fee-table td:first-child { text-align: left; }
.fee-note { font-size: 10pt; margin: 8px 0; }
.fee-note ul { padding-left: 20px; margin: 6px 0; }
.fee-note li { margin-bottom: 6px; }

/* ---------- Deadline table ---------- */
.deadline-table { width: 100%; border-collapse: collapse; font-size: 10pt; margin: 12px 0; }
.deadline-table th, .deadline-table td { border: 1px solid #666; padding: 6px 8px; vertical-align: top; }
.deadline-table th { background: #f5f5f5; font-weight: 700; }
.deadline-table tr { page-break-inside: avoid; }

/* ---------- FAQ ---------- */
.faq-section-title { font-weight: 700; font-size: 11pt; margin: 14px 0 6px; page-break-after: avoid; }
.faq-block { page-break-inside: avoid; margin-bottom: 8px; }
.faq-q { font-weight: 700; margin: 10px 0 2px; text-indent: 20px; page-break-after: avoid; }
.faq-a { margin: 0 0 8px 0; text-align: justify; }

/* ---------- Signature ---------- */
.sig { margin-top: 32px; page-break-inside: avoid; }
.sig-name { font-weight: 700; margin: 0 0 2px; }
.sig-desg { margin: 0; }

/* ---------- Footer ---------- */
.pg-footer { margin-top: 24px; padding-top: 8px; border-top: 1px solid #999; font-size: 8pt; color: #666; text-align: center; page-break-inside: avoid; }
</style>

<div class="nlsat-offer">

{# ══════════════════════════════════════════════════════════════════════ #}
{# COVER LETTER (PAGE 1) — no marker before this, it's the first page      #}
{# ══════════════════════════════════════════════════════════════════════ #}
<div class="section">
  <div class="lh">
    {% set pf_logo = frappe.db.get_value('Print Format', 'Offer Letter', 'logo') %}
    {% if pf_logo %}
      {% set pf_logo_url = (static_base_url ~ pf_logo) if pf_logo.startswith('/') else pf_logo %}
      <div style="text-align: center; margin-bottom: 10px;">
        <img src="{{ pf_logo_url }}" alt="Logo" style="max-width: 100%; height: auto; margin-top: 15px;">
      </div>
    {% else %}
      <table style="width: 100%; border-collapse: collapse; border: none; margin-bottom: 2px;">
        <tr>
          <td style="width: 22%; text-align: left; vertical-align: middle; padding: 0;">
            {% if campus and campus.logo %}
              {% set campus_logo_url = (static_base_url ~ campus.logo) if campus.logo.startswith('/') else campus.logo %}
              <img src="{{ campus_logo_url }}" alt="Logo" style="max-width: 120px; height: auto;">
            {% endif %}
          </td>
          <td style="width: 78%; text-align: center; vertical-align: middle; padding: 0;">
            <p class="lh-name" style="font-size: 15pt; font-weight: 700; margin: 0 0 6px; text-transform: uppercase;">{{ uni_name }}</p>
            <p class="lh-addr" style="font-size: 9.5pt; color: #333; margin: 0 0 6px;">{{ uni_address }}</p>
            <div style="border-top: 1px solid #333; margin: 4px 0 4px 0;"></div>
            <p class="lh-contact" style="font-size: 9pt; color: #333; margin: 0;">
              {% if uni_phone %}Telephone: {{ uni_phone }} &nbsp;|&nbsp; {% endif %}
              Website : www.nls.ac.in
              {% if uni_email %} &nbsp;|&nbsp; Email : {{ uni_email }}{% endif %}
            </p>
          </td>
        </tr>
      </table>
    {% endif %}
  </div>

  <p style="text-align: right;"><strong>Date:</strong> {{ frappe.utils.format_date(issued_date, "d MMMM yyyy") }}</p>
  <p><strong>Dear Candidate,</strong></p>
  <p style="font-size:12pt;">Congratulations on your performance in the National Law School Admission Test (NLSAT).</p>

  <p class="para">
    We are glad to provisionally offer you admission to the <strong>{{ prog_display }}</strong> programme at the
    {{ uni_name }}.
  </p>

  <p class="para">
    To accept this provisional offer of admission, you will need to complete the following.
  </p>

  <ol class="step-list">
    <li>You will need to log in to the <a href="https://app.nls.ac.in/admission/login#login">Admissions Portal</a> to accept the provisional offer of admission. The steps you need to follow are detailed in Appendix I.</li>
    <li>In order to confirm this provisional offer, you must pay Rs. {{ confirmation_fee_amt }} as a confirmation fee by {{ confirmation_deadline }}. The full fees applicable to the individual candidate for the academic year {{ academic_yr }} will have to be paid by {{ full_fee_deadline }}. Failure to pay the confirmation fee will result in the withdrawal of the admission offer. The fees schedule for all {% if is_mpp %}two{% else %}three{% endif %} years of study is given in Appendix II.</li>
    <li>The University is dedicated to ensuring that students admitted to an academic programme are provided with necessary support to study at NLSIU, irrespective of financial constraints. The Financial Aid Policy sets out the University's approach to delivering on this commitment. All candidates admitted to NLSIU are eligible for the PM Vidyalaxmi Scheme, which provides collateral-free and guarantor-free education loans. Candidates may additionally apply for financial aid from the University. The note on financial aid in Appendix III details this policy.</li>
    <li>This offer is contingent upon the verification of particulars furnished in the application form. In the next few days, you may receive an email from the NLSIU admissions team if there are queries on the information and documents submitted along with your application. Submitting incomplete, invalid, or false information/documents shall result in the withdrawal of the provisional offer of admission. A list of documents required is given in Appendix IV.</li>
    {% if is_ba %}
    <li>All students are eligible to apply for university-arranged housing. Further details about housing are available in Appendix V.</li>
    <li>You will be assigned the major indicated as your first preference in the application form. If you wish to change this preference, you may apply to do so during the registration process on {{ registration_date }}, subject to availability and the applicable academic regulations. You may also opt for a second major or minor at the end of the first year in accordance with the University's academic policies.</li>
    {% elif is_llb %}
    <li>All students of the LL.B. (Hons.) programmes are eligible to apply for off-campus accommodation. Please note that accommodation is limited and applying for accommodation does not guarantee allotment. Further details about accommodation are available in Appendix V.</li>
    {% elif is_mpp %}
    <li>All students of the MPP are eligible to apply for off-campus accommodation. Please note that applying for accommodation does not guarantee allotment, and the University is unable to guarantee housing. Further details about accommodation are available in Appendix V.</li>
    {% endif %}
    <li>You are required to be present at the NLSIU campus in Bengaluru, on {{ registration_date }}, onwards for registration and onboarding. The orientation programme will commence on {{ orientation_date }}. The schedule for the orientation will be announced later.</li>
    <li>On {{ registration_date }}, the University will conduct an in-person verification of the original certificates you have submitted via the admissions portal. Your provisional admission will be confirmed only after successful verification of the original documents. Failure to submit any of the above valid certificates at the time of verification shall result in the withdrawal of the provisional offer of admission.</li>
  </ol>

  <p class="para">
    Please refer to the Admissions FAQ in Appendix VI below for responses to common questions regarding the admission process. For any further queries, you may write to us at nlsat.query@nls.ac.in.
  </p>

  <p class="para">
    We look forward to welcoming you to the NLSIU community and to seeing you contribute to the academic and intellectual life of the University.
  </p>

  <div class="sig" style="margin-top: 40px;">
    <p class="sig-name">Registrar</p>
  </div>
</div>

{# ══════════════════════════════════════════════════════════════════════ #}
{# APPENDIX I — Steps to Accept the Provisional Offer                     #}
{# ══════════════════════════════════════════════════════════════════════ #}
<div class="page-break"></div>
<div class="section">
  <div class="lh">
    {% set pf_logo = frappe.db.get_value('Print Format', 'Offer Letter', 'logo') %}
    {% if pf_logo %}
      {% set pf_logo_url = (static_base_url ~ pf_logo) if pf_logo.startswith('/') else pf_logo %}
      <div style="text-align: center; margin-bottom: 10px;">
        <img src="{{ pf_logo_url }}" alt="Logo" style="max-width: 100%; height: auto; margin-top: 15px;">
      </div>
    {% else %}
      <table style="width: 100%; border-collapse: collapse; border: none; margin-bottom: 2px;">
        <tr>
          <td style="width: 22%; text-align: left; vertical-align: middle; padding: 0;">
            {% if campus and campus.logo %}
              {% set campus_logo_url = (static_base_url ~ campus.logo) if campus.logo.startswith('/') else campus.logo %}
              <img src="{{ campus_logo_url }}" alt="Logo" style="max-width: 120px; height: auto;">
            {% endif %}
          </td>
          <td style="width: 78%; text-align: center; vertical-align: middle; padding: 0;">
            <p class="lh-name" style="font-size: 15pt; font-weight: 700; margin: 0 0 6px; text-transform: uppercase;">{{ uni_name }}</p>
            <p class="lh-addr" style="font-size: 9.5pt; color: #333; margin: 0 0 6px;">{{ uni_address }}</p>
